package game

import (
 "encoding/json"
 "os"
 "path/filepath"
 "testing"
)

func TestExportRescueBaseline(t *testing.T) {
 out:=os.Getenv("SUNDOG_PARITY_OUTPUT")
 raw,err:=os.ReadFile(filepath.Join(out,"native-fuel-rescue.json"));if err!=nil{t.Fatal(err)}
 var native struct{
 Gates []struct{Pending bool;Planet,City,HomeCity int;Allowed bool}
 Rows []struct{Input struct{Time,Planet,City int;Seed [2]uint16};Due int;Trace struct{RawRandom []int}}
 };if err=json.Unmarshal(raw,&native);err!=nil{t.Fatal(err)}
 type row struct{Index int;Allowed bool;Time,Fuel,Due,Draws int;Pending,Refresh bool;Differences []string}
 gates,rows:=[]row{},[]row{}
 r,err:=NewReducer();if err!=nil{t.Fatal(err)}
 for idx,n:=range native.Gates{
  s:=NewState();s.Screen=ScreenShipboard;s.Fuel=0;s.FuelRescuePending=n.Pending
  a,err:=r.Step(s,ActionDistressCall);x:=row{Index:idx,Allowed:err==nil&&a.MessageKey=="ui.message.refuel_eta"}
  if x.Allowed!=n.Allowed{x.Differences=append(x.Differences,"gate")};gates=append(gates,x)
 }
 for idx,n:=range native.Rows{
  s:=NewState();s.Fuel=0;s.TimeMinutes=n.Input.Time;s.ShipRefresh=true
  if len(n.Trace.RawRandom)>0{
   want:=n.Trace.RawRandom[0]%51;found:=false
   for before:=0;before<10000;before++{p:=s;p.CombatRolls=before;if combatRoll(&p,51)==want{s.CombatRolls=before;found=true;break}}
   if !found{t.Fatal("controlled remainder unavailable")}
  }
  before:=s.CombatRolls;_,ok:=callForFuel(&s)
  x:=row{Index:idx,Allowed:ok,Time:s.TimeMinutes,Fuel:s.Fuel,Due:s.FuelRescueDue,Draws:s.CombatRolls-before,Pending:s.FuelRescuePending,Refresh:s.ShipRefresh}
  if x.Time!=n.Input.Time{x.Differences=append(x.Differences,"main-clock")}
  if x.Fuel!=0{x.Differences=append(x.Differences,"immediate-fuel")}
  if !x.Pending||x.Due!=n.Due||x.Refresh{x.Differences=append(x.Differences,"pending-eta-flags")}
  wantDraws:=0;if n.Input.Planet==0{wantDraws=1};if x.Draws!=wantDraws{x.Differences=append(x.Differences,"random-consumption")}
  rows=append(rows,x)
 }
 raw,err=json.MarshalIndent(struct{Scope string;Gates,Rows []row}{"修正前正式Shipboard動作資格與callForFuel數值；在單次RND餘數控制點對齊，未稱原版GUI或跨流程骰序相同。",gates,rows},"","  ");if err!=nil{t.Fatal(err)}
 if err=os.WriteFile(filepath.Join(out,"baseline.json"),append(raw,'\n'),0600);err!=nil{t.Fatal(err)}
}

